patch:
diff --git a/tmp-repro/no-lonely-if-19033.js b/tmp-repro/no-lonely-if-19033.js
new file mode 100644
index 0000000..e9a36ae
--- /dev/null
+++ b/tmp-repro/no-lonely-if-19033.js
@@ -0,0 +1,23 @@
+"use strict";
+const { Linter } = require(process.env.ESLINT_PATH || "../lib/api");
+console.log("eslint", require((process.env.ESLINT_PATH ? process.env.ESLINT_PATH + "/package.json" : "../package.json")).version);
+const linter = new Linter();
+const code = [
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');",
+    ""
+].join("\n");
+const config = { rules: { "no-lonely-if": "error" } };
+const messages = linter.verify(code, config);
+console.log("Messages:", messages.map(m => `${m.line}:${m.column} ${m.message}`));
+const { output } = linter.verifyAndFix(code, config);
+console.log("--- fixed output ---\n" + output);
+for (const [label, src] of [["original", code], ["fixed", output]]) {
+    try { new Function(src)(); console.log(`${label}: ran, no throw`); }
+    catch (e) { console.log(`${label}: THREW ${e.message}`); }
+}
+const ok = output === code || (() => { try { new Function(output)(); return true; } catch { return false; } })();
+process.exitCode = ok ? 0 : 1;
+console.log(ok ? "OK: fix preserves semantics" : "BUG: autofix changed semantics (else now binds to the inner if)");
